/**
 * Real project logos for two fixtures, so `mise run web:mock` shows what the portal actually
 * looks like with artwork rather than a grid of flat placeholder squares.
 *
 * Development and test only, like everything in this directory. These are the genuine bytes
 * the crawler fetched — each comment above records the URL `resolveIconCandidate` picked and
 * `mise run repo:icon -- --repo owner/name` downloaded — rasterised to the three derived sizes by
 * the same `sharp` step the real pipeline uses. Nothing here is invented: an icon is a claim
 * about whose project it is, and a mock that drew its own would teach the wrong thing.
 *
 * Every other fixture falls back to the flat placeholder in `handlers.ts`, which is what keeps
 * this file two repositories long instead of three hundred.
 */
export const MOCK_REAL_ICONS: Record<string, Record<number, string>> = {
  'argoproj/argo-cd': {
    // https://raw.githubusercontent.com/argoproj/argo-cd/master/docs/assets/logo.png
    32:
      '',
    64:
      '',
    160:
      '',
  },
  'aquasecurity/trivy': {
    // https://raw.githubusercontent.com/aquasecurity/trivy/main/docs/imgs/logo.png
    32:
      '',
    64:
      '',
    160:
      '',
  },
};

/** Decodes one base64 PNG into the bytes an `HttpResponse` can send. */
export const decodeIcon = (base64: string): Uint8Array =>
  Uint8Array.from(atob(base64), (character) => character.charCodeAt(0));
